"""Home editorial do Instituto Mais Amor. Conteúdo operacional depende de confirmação."""
def make_home(h):
 section,head,btn,link,icon,projectcards,faqs,care=(h[k] for k in ['section','head','btn','link','icon','projectcards','faqs','care'])
 puzzle='<svg class="puzzle-decoration" viewBox="0 0 180 180" aria-hidden="true"><path d="M20 20h45c-10 35 40 35 30 0h45v45c35-10 35 40 0 30v45H95c10-35-40-35-30 0H20V95c35 10 35-40 0-30Z"/></svg>'
 hero='''<section class="campaign-hero"><div class="wrap campaign-grid"><div class="campaign-copy"><div class="eyebrow"><span class="yellow-dot"></span>ACOLHIMENTO • INCLUSÃO • APOIO ÀS FAMÍLIAS</div><h1>Você não precisa<br>enfrentar tudo<br><span>sem apoio.</span></h1><p>O Instituto Mais Amor conecta acolhimento, saúde, educação, assistência social e defesa de direitos para fortalecer a inclusão, a autonomia e os vínculos familiares.</p><p>Com atenção às pessoas com síndrome de Down, pessoas autistas e com outras deficiências, nossa rede também se volta às mães atípicas, cuidadores e famílias em situação de vulnerabilidade. Conte sua necessidade e conheça os caminhos de cuidado e apoio que podemos construir juntos.</p><details class="hero-support"><summary>Conheça nossas frentes de cuidado</summary><p>As finalidades do Instituto incluem fonoaudiologia, terapia ocupacional, fisioterapia, psicologia e psicopedagogia; apoio às famílias e fortalecimento de vínculos; inclusão na educação, na cultura, no esporte, no lazer e no trabalho; oficinas, formação e orientação sobre direitos. As ações de solidariedade também podem incluir apoio alimentar. Cada iniciativa depende de equipe, estrutura e disponibilidade confirmadas.</p><a href="atuacao.html">Conhecer as áreas de atuação ↗</a></details><div class="actions">'''+btn('Quero solicitar acolhimento','acolhimento.html#solicitar-acolhimento','yellow')+btn('Conhecer o Instituto','instituto.html','outline-white')+'''</div><p class="hero-availability">Atendimentos, terapias e apoios dependem de disponibilidade e avaliação da equipe.</p><div class="hero-trust"><span class="trust-mark">'''+icon('heart')+'''</span><span>Acolhimento gratuito e escuta respeitosa.<br><strong>Sua história merece atenção.</strong></span></div></div>'''+(h['root']/'scripts/templates/hero-video-card.html').read_text()+'''</div>'''+puzzle+'''<div class="hero-bottom"><span>ACOLHER</span><i></i><span>CUIDAR</span><i></i><span>INCLUIR</span><i></i><span>TRANSFORMAR</span></div></section>'''
 paths=section('<div class="path-heading"><span class="section-kicker">UM PROPÓSITO. MUITAS POSSIBILIDADES.</span><h2>O amor aproxima.<br>A inclusão transforma.</h2><p>Saúde, educação, assistência social e defesa de direitos conectadas para construir uma rede de cuidado, oportunidades e pertencimento.</p></div><div class="path-grid">'+''.join('<a class="path-card" href="'+url+'"><span class="path-icon">'+icon(k)+'</span><h3>'+title+'</h3><p>'+desc+'</p><span class="path-arrow" aria-hidden="true">↗</span></a>' for k,title,desc,url in [('heart','Busco acolhimento','Conheça a proposta de escuta e aproximação com as famílias.','acolhimento.html'),('people','Quero fazer parte','Explore as possibilidades de voluntariado e participação.','voluntariado.html'),('hand','Quero construir junto','Conheça os caminhos para colaborar com o Instituto.','parcerias.html')])+'</div>','path-section')
 about=section('<div class="about-editorial"><div class="editorial-photo"><img src="assets/galeria/acolhimento-familias.webp" alt="Ilustração de uma profissional acolhendo uma mulher e uma criança" width="1200" height="800" loading="lazy"><div class="photo-corner brand-corner"><img src="assets/logo-instituto-mais-amor.jpeg" alt="Instituto Mais Amor" width="160" height="160"></div></div><div class="about-copy"><div class="eyebrow"><span class="dot"></span>QUEM SOMOS</div><h2>Uma rede de cuidado.<br>Um futuro com<br><span>mais possibilidades.</span></h2><p>O Instituto Mais Amor nasce da convicção de que todas as pessoas merecem respeito, oportunidades e condições para desenvolver suas capacidades.</p><p>Nossa proposta integra saúde, educação, assistência social e iniciativas de inclusão, valorizando o apoio às famílias e a defesa dos direitos das pessoas com deficiência e neurodivergentes.</p>'+link('Conheça nossa missão e nossos valores','instituto.html#missao')+'</div></div>','about-section')
 programs=[('assets/aprender-juntos.jpg','Menina participa de uma atividade de aprendizagem com cartas','Cuidado multidisciplinar','Diferentes áreas do conhecimento para valorizar cada caminho de desenvolvimento.','atendimento.html','SAÚDE E DESENVOLVIMENTO'),('assets/educacao-diversa.jpg','Professor e crianças participam de uma atividade em sala de aula','Inclusão e assistência social','Autonomia, participação, fortalecimento familiar e defesa de direitos.','inclusao.html','PERTENCIMENTO E CIDADANIA'),('assets/familia-inclusiva.jpg','Mãe e filha utilizam um computador juntas','Educação e oportunidades','Aprendizagem, formação e conhecimento para ampliar possibilidades.','atuacao.html','CONHECIMENTO E AUTONOMIA')]
 programs=section(head('NOSSA ATUAÇÃO','Cada pessoa é única.<br>O cuidado também precisa ser.','As áreas apresentadas fazem parte das finalidades institucionais. A disponibilidade de serviços depende de confirmação.')+'<div class="program-grid">'+''.join('<article class="program-card"><a href="'+url+'" tabindex="-1" aria-hidden="true"><img src="'+image+'" alt="" width="1200" height="800" loading="lazy"></a><div class="program-body"><span>'+tag+'</span><h3>'+title+'</h3><p>'+desc+'</p>'+link('Conheça a proposta',url)+'</div></article>' for image,alt,title,desc,url,tag in programs)+'</div>','program-section')
 projects=section(head('PROJETOS E INICIATIVAS','Histórias que merecem<br>novas possibilidades.','','projetos.html','Explore todos os projetos')+projectcards(3)+'<p class="section-footnote">Propostas institucionais em planejamento. Novas etapas e atividades serão comunicadas após confirmação.</p>','projects-section')
 commitment=section('<div class="commitment-editorial"><div><div class="eyebrow">NOSSO COMPROMISSO</div><h2>Cuidado e dignidade<br><span>não devem ser privilégios.</span></h2><p>As finalidades estatutárias estabelecem o compromisso com atividades, atendimentos e terapias gratuitos, contínuos e sem discriminação.</p><a class="button yellow" href="finalidades.html">Leia as finalidades institucionais <span aria-hidden="true">↗</span></a></div><div class="commitment-values"><details class="commitment-detail"><summary><span class="value-number">01</span><span class="value-intro"><strong>Gratuidade</strong><span>Compromisso institucional com o acesso gratuito.</span></span><span class="value-toggle" aria-hidden="true"></span></summary><div class="value-explanation"><p>O compromisso do Instituto é construir ações, atividades e possibilidades de cuidado com acesso gratuito, conforme suas finalidades institucionais. Isso significa que a condição financeira de uma família não deve ser tratada como medida do valor de uma pessoa ou do seu direito ao acolhimento. As iniciativas ainda dependem de estrutura, equipe, planejamento e confirmação de disponibilidade. A gratuidade não representa garantia de vaga, agendamento ou atendimento imediato; cada possibilidade será comunicada com clareza pelos canais institucionais.</p></div></details><details class="commitment-detail"><summary><span class="value-number">02</span><span class="value-intro"><strong>Igualdade</strong><span>Respeito às pessoas, à diversidade e aos direitos.</span></span><span class="value-toggle" aria-hidden="true"></span></summary><div class="value-explanation"><p>Igualdade é reconhecer que todas as pessoas têm o mesmo valor e merecem respeito e oportunidades de participação. Na prática, isso envolve acolher diferentes origens, identidades, condições sociais e necessidades de apoio, sem discriminação. Também exige equidade: oferecer recursos e adaptações de acordo com as barreiras enfrentadas por cada pessoa. A proposta do Instituto é construir relações de escuta e respeito, com informações claras e critérios transparentes para as iniciativas que forem disponibilizadas.</p></div></details><details class="commitment-detail"><summary><span class="value-number">03</span><span class="value-intro"><strong>Dignidade</strong><span>Valorização de cada vida e de suas possibilidades.</span></span><span class="value-toggle" aria-hidden="true"></span></summary><div class="value-explanation"><p>Dignidade é reconhecer cada pessoa como sujeito de direitos, com história, preferências, capacidades e projetos de vida próprios. O cuidado deve preservar a autonomia, a privacidade e a participação nas decisões que afetam a própria vida. Isso significa usar linguagem respeitosa, evitar exposição indevida e ouvir a pessoa e sua família sem reduzir ninguém a uma condição, diagnóstico ou dificuldade. O compromisso do Instituto é valorizar potencialidades e construir relações de cuidado com respeito e responsabilidade.</p></div></details></div></div>','navy puzzle-surface')
 welcome=section('<div class="welcome-grid"><div><div class="eyebrow"><span class="dot"></span>MAIS AMOR PERTO DE VOCÊ</div><h2>Você e sua família<br>merecem ser ouvidos.</h2><p>Uma proposta de canal de aproximação para acolher o primeiro contato, ouvir necessidades e orientar sobre possibilidades conforme a estrutura disponível.</p>'+btn('Conheça o acolhimento','acolhimento.html')+'</div><div class="welcome-steps">'+''.join('<article><span>'+n+'</span><div><h3>'+title+'</h3><p>'+desc+'</p></div></article>' for n,title,desc in [('01','Conte sua história','O primeiro contato começa com a sua necessidade.'),('02','Uma escuta com respeito','Acolhimento humano, conforme a estrutura disponível.'),('03','Caminhos possíveis','Informações e eventuais orientações para os próximos passos.')])+'</div></div>','welcome-section')
 integrated=section(head('CUIDADO INTEGRADO','Pessoas e famílias<br>no centro de tudo.')+care,'integrated-section')
 participate=section('<div class="participate-editorial"><div><div class="eyebrow">VAMOS CONSTRUIR JUNTOS?</div><h2>O próximo capítulo<br>pode ter <span>você.</span></h2><p>Seu tempo, seu conhecimento e seu compromisso podem contribuir para uma sociedade com mais inclusão.</p><div class="actions">'+btn('Quero Ser Parceiro','parcerias.html')+btn('Seja Voluntário','voluntariado.html','light')+'</div></div><div class="participate-graphic" aria-hidden="true">'+puzzle+'<span>Mais encontros.<br>Mais oportunidades.<br><strong>Mais amor.</strong></span></div></div>','participate-section')
 faq=section(head('PERGUNTAS FREQUENTES','Informação também<br>é acolhimento.')+faqs,'soft')
 inclusion=section('<div class="inclusion-editorial"><div class="inclusion-image"><img src="assets/galeria/convivencia-parque.webp" alt="Ilustração de crianças convivendo e brincando em um parque" width="1672" height="941" loading="lazy"><p>Imagem ilustrativa criada com inteligência artificial. Não representa uma atividade real do Instituto.</p></div><div class="inclusion-message"><div class="eyebrow">O NOSSO LUGAR É JUNTOS.</div><h2>Uma inclusão<br>que abraça<br><span>todas as pessoas.</span></h2><p>Pessoas com síndrome de Down, pessoas autistas e com outras deficiências, pessoas negras e famílias diversas fazem parte de uma sociedade que merece respeito, acessibilidade e oportunidades.</p><div class="inclusion-tags" role="group" aria-label="Conheça os temas de inclusão"><button type="button" id="topic-button-down" class="inclusion-topic" aria-expanded="false" aria-controls="topic-down">Síndrome de Down<span aria-hidden="true"> +</span></button><button type="button" id="topic-button-autismo" class="inclusion-topic" aria-expanded="false" aria-controls="topic-autismo">Autismo<span aria-hidden="true"> +</span></button><button type="button" id="topic-button-diversidade" class="inclusion-topic" aria-expanded="false" aria-controls="topic-diversidade">Diversidade racial<span aria-hidden="true"> +</span></button><button type="button" id="topic-button-acessibilidade" class="inclusion-topic" aria-expanded="false" aria-controls="topic-acessibilidade">Acessibilidade<span aria-hidden="true"> +</span></button><button type="button" id="topic-button-inclusao" class="inclusion-topic" aria-expanded="false" aria-controls="topic-inclusao">Inclusão para todos<span aria-hidden="true"> +</span></button></div><div class="inclusion-explanations"><section id="topic-down" class="inclusion-explanation" aria-labelledby="topic-button-down" hidden><h3>Síndrome de Down</h3><p>É uma condição genética relacionada à presença de material extra do cromossomo 21. Cada pessoa tem características e necessidades próprias. O acompanhamento de saúde e os apoios à aprendizagem, comunicação e autonomia devem ser individualizados, com participação da família e de profissionais qualificados.</p><a href="https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-pessoa-com-deficiencia/publicacoes/diretrizes-de-atencao-a-pessoa-com-sindrome-de-down.pdf/view" target="_blank" rel="noopener noreferrer">Saiba mais: Ministério da Saúde ↗</a></section><section id="topic-autismo" class="inclusion-explanation" aria-labelledby="topic-button-autismo" hidden><h3>Autismo</h3><p>O transtorno do espectro autista é uma condição do neurodesenvolvimento que pode envolver diferenças na comunicação e interação social, nos interesses, nos comportamentos e na percepção sensorial. As necessidades de apoio variam de pessoa para pessoa. Apoios educacionais, comunicação acessível e acompanhamento individualizado podem favorecer bem-estar, participação e autonomia, respeitando as preferências da pessoa.</p><a href="https://www.who.int/news-room/fact-sheets/detail/autism-spectrum-disorders" target="_blank" rel="noopener noreferrer">Saiba mais: Organização Mundial da Saúde ↗</a></section><section id="topic-diversidade" class="inclusion-explanation" aria-labelledby="topic-button-diversidade" hidden><h3>Diversidade racial</h3><p>É o reconhecimento e a valorização das diferentes identidades, origens e experiências étnico-raciais. Promover essa diversidade significa respeitar as pessoas, enfrentar o racismo e criar oportunidades de participação com igualdade de direitos.</p></section><section id="topic-acessibilidade" class="inclusion-explanation" aria-labelledby="topic-button-acessibilidade" hidden><h3>Acessibilidade</h3><p>É criar condições para que pessoas com diferentes necessidades possam acessar espaços, informações, serviços e oportunidades com autonomia e segurança. Isso inclui remover barreiras físicas, digitais, de comunicação e de atitudes.</p></section><section id="topic-inclusao" class="inclusion-explanation" aria-labelledby="topic-button-inclusao" hidden><h3>Inclusão para todos</h3><p>É garantir pertencimento e participação, respeitando as diferenças e oferecendo os apoios de que cada pessoa precisa. A inclusão se constrói com escuta, acessibilidade, respeito e oportunidades reais.</p></section></div>'+btn('Conheça nosso compromisso','inclusao.html','yellow')+'</div></div>','inclusion-section')
 admin_access='<section class="section admin-access-section" aria-labelledby="admin-access-title"><div class="wrap"><div class="admin-access-card"><div class="admin-access-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg></div><div class="admin-access-copy"><div class="eyebrow">GESTÃO DO INSTITUTO</div><h2 id="admin-access-title">Acesso administrativo</h2><p>Consulte os cadastros, acompanhe as solicitações e organize os contatos do Instituto.</p><small>Área exclusiva para a administração. Entre com sua conta autorizada do ChatGPT.</small></div><a class="button admin-access-button" href="/admin" target="_top">Entrar no painel <span aria-hidden="true">↗</span></a></div></div></section>'
 return hero+paths+about+inclusion+programs+projects+commitment+welcome+integrated+participate+faq+admin_access
